import { test, expect } from '@playwright/test';

test.describe('File Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/upload'); // Replace with the actual URL
  });

  test('should display the file name after selecting a file', async ({ page }) => {
    const filePath = 'path/to/your/file.txt'; // Replace with the actual file path
    await page.getByLabel('Upload File').setInputFiles(filePath);

    const fileName = await page.getByText('file.txt'); // Replace with the expected file name
    expect(fileName).toBeVisible();
  });

  test('should display the file size after selecting a file', async ({ page }) => {
    const filePath = 'path/to/your/file.txt'; // Replace with the actual file path
    await page.getByLabel('Upload File').setInputFiles(filePath);

    const fileSize = await page.getByText('Size: 1 KB'); // Replace with the expected file size
    expect(fileSize).toBeVisible();
  });
});
